/// The units of the `startOf` and `endOf` cases of a zone.
const List<String> dateReferenceLocalUnits = [
  'hour',
  'day',
  'week',
  'isoweek',
  'month',
  'year',
];

/// The weekdays of the `startOf(time, 'isoWeek', weekday)` cases of a
/// zone.
